CREATE PROCEDURE [sales].[POS_ReturnInvoice] @InvoiceId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@Reason NVARCHAR(250),@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF ISJSON(@ItemsJson)<>1 THROW 51100,'Return items are required.',1;DECLARE @WarehouseId UNIQUEIDENTIFIER,@ReturnTransactionId UNIQUEIDENTIFIER=NEWID(),@ReturnNo NVARCHAR(50)=CONCAT('RET-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),20))),@Refund DECIMAL(18,2)=0;SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;SELECT @WarehouseId=WarehouseId FROM sales.SalesInvoices WITH(UPDLOCK)WHERE InvoiceId=@InvoiceId AND Status IN('COMPLETED','PARTIALLY_RETURNED');IF @WarehouseId IS NULL BEGIN ROLLBACK;THROW 51100,'Invoice is not returnable.',1;END;INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@ReturnTransactionId,@ReturnNo+'-STK','RETURN','SALES_RETURN',@InvoiceId,@WarehouseId,@Reason,@CreatedBy);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT InvoiceItemId,Quantity FROM OPENJSON(@ItemsJson)WITH(InvoiceItemId UNIQUEIDENTIFIER,Quantity DECIMAL(18,4));DECLARE @ItemId UNIQUEIDENTIFIER,@Qty DECIMAL(18,4),@ProductId UNIQUEIDENTIFIER,@Sold DECIMAL(18,4),@Returned DECIMAL(18,4),@LineTotal DECIMAL(18,2),@UnitCost DECIMAL(18,4),@BalanceId UNIQUEIDENTIFIER;OPEN c;FETCH NEXT FROM c INTO @ItemId,@Qty;WHILE @@FETCH_STATUS=0 BEGIN SELECT @ProductId=ProductId,@Sold=Quantity,@Returned=ReturnedQuantity,@LineTotal=LineTotal FROM sales.SalesInvoiceItems WITH(UPDLOCK)WHERE InvoiceItemId=@ItemId AND InvoiceId=@InvoiceId;IF @ProductId IS NULL OR @Qty<=0 OR @Returned+@Qty>@Sold BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51100,'Invalid return quantity.',1;END;SET @Refund=@Refund+(@LineTotal/@Sold*@Qty);UPDATE sales.SalesInvoiceItems SET ReturnedQuantity=ReturnedQuantity+@Qty WHERE InvoiceItemId=@ItemId;INSERT sales.SalesInvoiceReturns(ReturnNumber,InvoiceId,InvoiceItemId,Quantity,RefundAmount,Reason,CreatedBy)VALUES(CONCAT(@ReturnNo,'-',RIGHT(CONVERT(NVARCHAR(36),@ItemId),4)),@InvoiceId,@ItemId,@Qty,@LineTotal/@Sold*@Qty,@Reason,@CreatedBy);SELECT @BalanceId=InventoryBalanceId,@UnitCost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@ProductId AND WarehouseId=@WarehouseId AND ZoneId IS NULL AND BinId IS NULL AND BatchNo IS NULL AND SerialNo IS NULL;IF @BalanceId IS NULL BEGIN SET @BalanceId=NEWID();INSERT inventory.InventoryBalances(InventoryBalanceId,ProductId,WarehouseId,CreatedBy)VALUES(@BalanceId,@ProductId,@WarehouseId,@CreatedBy);END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand+@Qty,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@BalanceId;INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,Quantity,UnitCost)VALUES(@ReturnTransactionId,@ProductId,@Qty,ISNULL(@UnitCost,0));FETCH NEXT FROM c INTO @ItemId,@Qty;END;CLOSE c;DEALLOCATE c;UPDATE sales.SalesInvoices SET Status=CASE WHEN NOT EXISTS(SELECT 1 FROM sales.SalesInvoiceItems WHERE InvoiceId=@InvoiceId AND ReturnedQuantity<Quantity)THEN'RETURNED'ELSE'PARTIALLY_RETURNED'END,ModifiedOn=SYSUTCDATETIME()WHERE InvoiceId=@InvoiceId;COMMIT;SELECT @InvoiceId InvoiceId,@ReturnNo ReturnNumber,@Refund RefundAmount,@ReturnTransactionId TransactionId;END;
